typedef struct {
    uint8_t transfer;                /* DC_TRANSFER_* */
    uint16_t data_type_id;
    uint16_t crc_seed;
    uint8_t destination;             /* services */
    uint8_t priority;                /* 0 (highest) to 31 */
    uint8_t transfer_id;
    bool fd;                         /* CAN FD frames */
    uint8_t iface_mask;              /* 0: every interface */
    uint64_t deadline_us;            /* 0: now + DC_TX_TIMEOUT_US */
    const uint8_t* payload;
    uint16_t length;
} dc_tx_t;

/* Queue a transfer with an explicit transfer ID.  Returns frames queued or DC_ERR_*.
 * All frames are queued or none.  While anonymous, only single-frame messages with data type
 * ID 0..3 can be sent (DC_ERR_ANONYMOUS, DC_ERR_ARGUMENT). */
int32_t dc_send(dc_node_t* node, const dc_tx_t* tx, uint64_t now_us);
/* Broadcast with the node's own transfer ID for this message type. */
int32_t dc_publish(dc_node_t* node, uint16_t data_type_id, uint16_t crc_seed, uint8_t priority,
                   const uint8_t* payload, uint16_t length, uint64_t now_us);
/* Send a request; the handler gets the response, or a transfer with timed_out set after
 * DC_REQUEST_TIMEOUT_US.  Needs a DC_TRANSFER_RESPONSE subscription for the type (for
 * reassembly).  Returns the transfer ID or DC_ERR_*. */
int32_t dc_request(dc_node_t* node, uint8_t server, uint16_t data_type_id, uint16_t crc_seed, uint8_t priority,
                   const uint8_t* payload, uint16_t length, uint64_t now_us, dc_handler_t handler, void* user);
/* Answer a request with its transfer ID and priority. */
int32_t dc_respond(dc_node_t* node, const dc_transfer_t* request, uint16_t crc_seed,
                   const uint8_t* payload, uint16_t length, uint64_t now_us);
#endif /* DC_PROFILE_BOOTLOADER */

